def countAllowedStrings(n, k, pairs):
    MOD = 10 ** 9 + 7
    M = [[0] * k for _ in range(k)]
    for x, y in pairs:
        M[x][y] = 1

    def mat_mul(A, B):
        C = [[0] * k for _ in range(k)]
        for i in range(k):
            Ai = A[i]
            Ci = C[i]
            for t in range(k):
                a = Ai[t]
                if a:
                    Bt = B[t]
                    for j in range(k):
                        Ci[j] += a * Bt[j]
            for j in range(k):
                Ci[j] %= MOD
        return C

    v = [1] * k
    e = n - 1
    while e:
        if e & 1:
            v = [sum(M[i][j] * v[j] for j in range(k)) % MOD for i in range(k)]
        M = mat_mul(M, M)
        e >>= 1
    return sum(v) % MOD
